def e(v): return html.escape(str(v),quote=True)
def localized(c,key,source): return TRANS.get(lang(c),{}).get(key,source)
def lang(c): return LOCALES[c]["language"]
def tr(c): return C[lang(c)]
def slug(c): return c.lower()
def url(c,tail=""): return BASE+"/"+slug(c)+"/"+(tail.strip("/")+"/" if tail else "")
def flags(tail=""):
 return "".join(f'<a class="locale-flag" lang="{c}" href="{url(c,tail)}" aria-label="{e(LOCALES[c]["name"])}"><img src="https://flagcdn.com/w80/{LOCALES[c]["flag"]}.png" alt="{e(LOCALES[c]["name"])} flag" width="40" height="30" loading="lazy"></a>' for c in PUB)
def header(c,tail=""):
 t=tr(c); groups=""
 for group,items,label in (("primary",SECTIONS,t["about"]),("resources",HUBS,t["tips"])):
  groups+=f'<details class="nav-menu" data-nav-group="{group}"><summary>{e(label)}</summary><div class="nav-dropdown">'
  groups+="".join(f'<a data-nav-item="{x}" href="{url(c,x)}">{e(t[x])}</a>' for x in items)+"</div></details>"
 return f'<header><div class="header-main"><div class="locale-switch">{flags(tail)}</div><a class="brand" href="{url(c,"about")}">{e(t["brand"])}</a><nav aria-label="{e(t["nav"])}">{groups}</nav></div></header>'
def app_schema(canonical):
 return {"@type":"SoftwareApplication","@id":BASE+"/#app","name":APP["name"],"operatingSystem":"Android","applicationCategory":"Dating","identifier":APP["package_id"],"downloadUrl":PLAY,"installUrl":PLAY,"url":canonical,"description":APP["description"],"image":[s["src"] for s in SHOTS],"sameAs":[PLAY],"publisher":{"@type":"Organization","name":APP["developer"]}}
def layout(c,tail,title,desc,body,extra=None,typ="WebPage"):
 canonical=url(c,tail); t=tr(c); seo=SEO.get(lang(c),{}).get(tail or "home",{}); title=seo.get("title",title); desc=seo.get("description",desc)
 alternates="".join(f'<link rel="alternate" hreflang="{x}" href="{url(x,tail)}">' for x in PUB)+f'<link rel="alternate" hreflang="x-default" href="{url("en-US",tail)}">'
 graph=[{"@context":"https://schema.org",**app_schema(canonical)},{"@context":"https://schema.org","@type":typ,"name":title,"description":desc,"url":canonical,"inLanguage":c}]
 if extra: graph.extend(extra)
 schema={"@context":"https://schema.org","@graph":graph}
 return f'''<!doctype html><html lang="{e(c)}" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="{("noindex,follow" if tail=="" or tail in HUBS or tail.startswith("features/") else "index,follow,max-image-preview:large")}"><link rel="canonical" href="{canonical}">{alternates}<meta property="og:type" content="website"><meta property="og:site_name" content="{e(APP["name"])}"><meta property="og:locale" content="{c.replace("-","_")}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{SHOTS[0]["src"]}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(desc)}"><meta name="twitter:image" content="{SHOTS[0]["src"]}"><link rel="stylesheet" href="{BASE}/assets/style.css"><script async src="https://www.googletagmanager.com/gtag/js?id={APP["ga4_measurement_id"]}"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments);}}gtag("js",new Date());gtag("config","{APP["ga4_measurement_id"]}");document.addEventListener("click",function(ev){{const a=ev.target.closest("a");if(a&&a.href==="{PLAY}")gtag("event","google_play_click",{{page_location:location.href}});}});</script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><a class="skip-link" href="#main">{e(t["skip"])}</a>{header(c,tail)}<main id="main">{body}</main><footer><span>© {e(APP["developer"])} · {e(APP["name"])}</span><span><a href="{e(APP["privacy_policy_url"])}">{e(t["privacy"])}</a> · <a href="mailto:{e(APP["support_email"])}">{e(t["support"])}</a></span></footer></body></html>'''
def render(c,section):
 t=tr(c); F=localized(c,"features",FEATURES); Q=localized(c,"faq",FAQ); title=t["home_title"] if section in ("home","about") else {"features":t["features"],"download":t["download"],"faq":t["faq"]}[section]
 desc=t["home_desc"] if section in ("home","about") else (t["resource"] if section=="features" else (t["notice"] if section=="download" else "Answers about profiles, matches, messages, filters and installing the app."))
 body=""
 if section in ("home","about"):
  body=f'<section class="hero"><p class="eyebrow">{e(t["tag"])}</p><h1>{e(title)}</h1><p class="lead">{e(t["intro"])}</p><a class="button" href="{PLAY}">{e(t["cta"])}</a></section><section class="section"><h2>{e(t["features"])}</h2><div class="cards">'
  body+="".join(f'<article><h3>{e(f["title"])}</h3><p>{e(f["description"])}</p></article>' for f in F)
  body+='</div><h2>App screenshots</h2><div class="shots">'+"".join(f'<figure><img src="{s["src"]}" alt="{e(s["alt"])}" width="526" height="296" loading="lazy"><figcaption>{e(s["caption"])}</figcaption></figure>' for s in SHOTS)+'</div></section>'
 elif section=="features":
  body=f'<section class="section"><h1>{e(title)}</h1><p class="lead">{e(t["intro"])}</p><div class="cards">'+"".join(f'<article><h2>{e(f["title"])}</h2><p>{e(f["description"])}</p></article>' for f in FEATURES)+'</div></section>'
 elif section=="download":
  body=f'<section class="hero"><h1>{e(t["download"])}</h1><p class="lead">{e(desc)}</p><ol><li>{e(t["step1"])}</li><li>{e(t["step2"])}</li><li>{e(t["step3"])}</li></ol><a class="button" href="{PLAY}">{e(t["cta"])}</a><p>{e(t["notice"])}</p><dl><dt>{e(t["platform"])}</dt><dd>Android</dd><dt>{e(t["developer"])}</dt><dd>{e(APP["developer"])}</dd><dt>{e(t["package"])}</dt><dd>{e(APP["package_id"])}</dd><dt>{e(t["age"])}</dt><dd>{e(APP["content_rating"])}</dd></dl></section>'
 else:
  body=f'<section class="section"><h1>{e(t["faq"])}</h1><div class="cards">'+"".join(f'<article><h2>{e(x["q"])}</h2><p>{e(x["a"])}</p></article>' for x in Q)+'</div></section>'
 body+=f'<section class="cta"><a class="button" href="{PLAY}">{e(t["cta"])}</a></section>'
 extra=[{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":x["q"],"acceptedAnswer":{"@type":"Answer","text":x["a"]}} for x in Q]}] if section=="faq" else None
 return layout(c,"" if section=="home" else section,title,desc,body,extra)
def resource(c,hub):
 t=tr(c); titles={"tips":"Tips for thoughtful connections","blog":"Dating, friendship and networking","guide":"How to use the app","comparison":"Explore different kinds of connections"}
 fr={"tips":"Conseils pour créer des liens","blog":"Rencontres, amitié et réseautage","guide":"Guide d’utilisation de l’application","comparison":"Différents types de relations"}
 es={"tips":"Consejos para conectar","blog":"Citas, amistad y contactos","guide":"Cómo usar la aplicación","comparison":"Tipos de conexiones"}
 pt={"tips":"Dicas para criar ligações","blog":"Encontros, amizade e contactos","guide":"Como utilizar a aplicação","comparison":"Tipos de ligações"}
 de={"tips":"Tipps für neue Kontakte","blog":"Dating, Freundschaft und Networking","guide":"App-Anleitung","comparison":"Verschiedene Arten von Kontakten"}
 it={"tips":"Consigli per creare connessioni","blog":"Incontri, amicizia e networking","guide":"Guida all’app","comparison":"Tipi di connessione"}
 title=(titles if lang(c)=="en" else {"fr":fr,"es":es,"pt":pt,"de":de,"it":it}[lang(c)])[hub]; desc=t["resource"]
 cards={"tips":[("Choose your intentions","Think about whether you are looking for dating, friendship or professional connections."),("Build an authentic profile","Use photos, a thoughtful bio, prompts and interests to introduce yourself."),("Start conversations respectfully","Take time to read profiles and communicate with care.")],"blog":[("Dating and first impressions","Ideas for introducing yourself and making a thoughtful first impression."),("Friendship and shared interests","Use shared interests as a natural starting point for new friendships."),("Professional connections","Approach networking with clear intentions and respectful communication.")],"guide":[("Create your profile","Add photos, a bio, prompts and interests."),("Set discovery filters","Use the available age, distance and intentions filters."),("Chat and keep in touch","The listing describes text, photo and voice-note conversations.")],"comparison":[("Dating","Explore profiles and express interest when you find a connection."),("Friendship","Discover people to chat with, go out with or travel with."),("Professional networking","Connect with professionals who share your ambitions.")]}[hub]
 body=f'<section class="section"><h1>{e(title)}</h1><p class="lead">{e(desc)}</p><div class="cards">'+"".join(f'<article><h2>{e(a)}</h2><p>{e(b)}</p></article>' for a,b in cards)+'</div></section>'
 return layout(c,hub,title,desc,body,typ="CollectionPage")
def feature_page(c,f):
 f=next(x for x in localized(c,"features",FEATURES) if x["id"]==f["id"]); tail="features/"+f["id"]; body=f'<section class="section"><h1>{e(f["title"])}</h1><p class="lead">{e(f["description"])}</p><a class="button" href="{PLAY}">{e(tr(c)["cta"])}</a></section>'
 return layout(c,tail,f["title"],f["description"],body)
def main():
 if DIST.exists(): shutil.rmtree(DIST)
 (DIST/"assets").mkdir(parents=True,exist_ok=True)
 css="""*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#f4f6fb;font:16px/1.7 system-ui,sans-serif}a{color:inherit}header,main,footer{width:min(1160px,calc(100% - 36px));margin:auto}.header-main{display:flex;align-items:center;gap:22px;flex-wrap:wrap;padding:22px 0}.brand{font-size:1.3rem;font-weight:800;text-decoration:none}.locale-switch{display:flex;gap:7px}.locale-flag img{display:block;width:32px;height:24px;object-fit:cover;border-radius:4px;border:1px solid #ffffff55}.header-main nav{display:flex;gap:10px;margin-inline-start:auto;flex-wrap:wrap}.nav-menu{position:relative}.nav-menu summary{cursor:pointer;padding:8px 13px;border:1px solid #34405c;border-radius:12px;list-style:none}.nav-dropdown{position:absolute;z-index:5;right:0;top:42px;min-width:190px;padding:8px;background:#17213a;border:1px solid #34405c;border-radius:12px;display:none}.nav-menu[open] .nav-dropdown{display:grid}.nav-dropdown a{padding:8px;text-decoration:none}.hero,.section,.cta{padding:clamp(28px,6vw,72px) 0}.hero{max-width:900px}.eyebrow{color:#f4c542;font-weight:800;letter-spacing:.1em}.hero h1{font-size:clamp(2.4rem,6vw,4.8rem);line-height:1.08}.lead{font-size:1.25rem;color:#c7d1e3;max-width:850px}.button{display:inline-flex;margin:18px 0;padding:13px 22px;border-radius:12px;background:#f4c542;color:#171717;font-weight:800;text-decoration:none}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.cards article,figure{margin:0;padding:20px;background:#141e34;border:1px solid #293752;border-radius:16px}.shots{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.shots img{width:100%;height:auto;border-radius:10px}.shots figcaption,footer{color:#c7d1e3}footer{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:28px 0;border-top:1px solid #293752}.skip-link{position:absolute;left:-9999px}.skip-link:focus{left:12px;top:12px;background:white;color:#111;padding:10px;z-index:10}dl{display:grid;grid-template-columns:180px 1fr;gap:8px}dt{font-weight:700}dd{margin:0}@media(max-width:700px){.header-main nav{margin:0;width:100%}.nav-dropdown{left:0;right:auto}}"""
 (DIST/"assets/style.css").write_text(css,encoding="utf-8")
 target=url("en-US","about")
 (DIST/"index.html").write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="google-site-verification" content="8mOiNMu4Tn477yFaR-IWrNQGhdqH1TpF6NKKoN94Oms"><meta name="robots" content="noindex,follow"><title>{e(APP["name"])}</title><link rel="canonical" href="{target}"><meta http-equiv="refresh" content="0; url={target}"><script>window.location.replace("{target}");</script></head><body><a href="{target}">Continue</a></body></html>',encoding="utf-8")
 routes=[]
 for c in PUB:
  for sec in ("home",)+SECTIONS:
   tail="" if sec=="home" else sec; p=DIST/slug(c)/(tail or "")/"index.html"; p.parent.mkdir(parents=True,exist_ok=True); p.write_text((f'<!doctype html><html lang="{e(c)}"><head><meta charset="utf-8"><meta name="robots" content="noindex,follow"><title>{e(APP["name"])}</title><link rel="canonical" href="{url(c,"about")}"><meta http-equiv="refresh" content="0; url={url(c,"about")}"><script>window.location.replace("{url(c,"about")}");</script></head><body><a href="{url(c,"about")}">Continue</a></body></html>' if sec=="home" else render(c,sec)),encoding="utf-8");
   if tail: routes.append((url(c,tail),tail))
  for f in FEATURES:
   tail="features/"+f["id"]; p=DIST/slug(c)/tail/"index.html"; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(feature_page(c,f),encoding="utf-8")
  for h in HUBS:
   p=DIST/slug(c)/h/"index.html"; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(resource(c,h),encoding="utf-8")
 (DIST/"robots.txt").write_text(f"User-agent: *\nAllow: /\n\nSitemap: {BASE}/sitemap.xml\nSitemap: {BASE}/sitemap.txt\n",encoding="utf-8")
 ns="http://www.sitemaps.org/schemas/sitemap/0.9"; xn="http://www.w3.org/1999/xhtml"; ET.register_namespace("",ns); ET.register_namespace("xhtml",xn); root=ET.Element("{%s}urlset"%ns)
 for loc,tail in routes:
  n=ET.SubElement(root,"{%s}url"%ns); ET.SubElement(n,"{%s}loc"%ns).text=loc
  for c in PUB: ET.SubElement(n,"{%s}link"%xn,{"rel":"alternate","hreflang":c,"href":url(c,tail)})
  ET.SubElement(n,"{%s}link"%xn,{"rel":"alternate","hreflang":"x-default","href":url("en-US",tail)})
 ET.ElementTree(root).write(DIST/"sitemap.xml",encoding="utf-8",xml_declaration=True)
 (DIST/"sitemap.txt").write_text("\n".join(x[0] for x in routes)+"\n",encoding="utf-8")
 (DIST/"llms.txt").write_text("# "+APP["name"]+"\n\n"+APP["description"]+"\n\n- Google Play: "+PLAY+"\n- Website: "+BASE+"/\n"+"".join("- "+c+": "+url(c)+"\n" for c in PUB),encoding="utf-8")
if __name__=="__main__": main()
